.s2-screen,.s2-screen *{box-sizing:border-box;margin:0;padding:0;}
.s2-screen{position:relative;width:390px;height:844px;overflow:hidden;background:#090c14;color:#e8eaf0;font-family:'Satoshi','Helvetica Neue',system-ui,-apple-system,Arial,sans-serif;font-weight:400;line-height:1.5;-webkit-font-smoothing:antialiased;}
.s2-hero{position:relative;overflow:hidden;padding:52px 24px 8px;}
.s2-glow{position:absolute;border-radius:50%;pointer-events:none;filter:blur(26px);background:radial-gradient(closest-side,rgba(45,212,191,0.13),transparent 70%);top:-140px;left:10px;width:360px;height:300px;z-index:0;}
.s2-heroin{position:relative;z-index:1;}
.s2-eyebrow{font-size:10.5px;text-transform:uppercase;font-weight:600;color:#7e8a9e;letter-spacing:0.16em;}
.s2-greet{font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:31px;line-height:1.15;color:#e8eaf0;margin-top:6px;}
.s2-sub{font-size:14px;line-height:20px;color:#a9b2c1;margin-top:6px;}

.s2-focus{position:relative;overflow:hidden;display:block;margin-top:20px;padding:20px;border-radius:24px;background:rgba(255,255,255,0.03);border:1px solid rgba(45,212,191,0.16);}
.s2-focus-glow{top:-70px;right:-50px;width:220px;height:200px;left:auto;}
.s2-focus-in{position:relative;z-index:1;}
.s2-focus-label{font-size:10.5px;text-transform:uppercase;font-weight:600;color:#2dd4bf;letter-spacing:0.16em;}
.s2-focus-h{font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:24px;color:#e8eaf0;margin-top:6px;}
.s2-focus-p{font-size:12.5px;color:#a9b2c1;margin-top:4px;}
.s2-focus-btn{display:inline-block;margin-top:16px;border-radius:9999px;font-weight:700;font-size:13.5px;padding:10px 20px;background:#2dd4bf;color:#06231f;box-shadow:0 8px 24px rgba(45,212,191,0.25);}

.s2-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:12px;}
.s2-tile{padding:16px;border-radius:16px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);}
.s2-tile-label{font-size:10.5px;text-transform:uppercase;font-weight:600;color:#7e8a9e;letter-spacing:0.16em;white-space:nowrap;}
.s2-weeks{display:flex;align-items:baseline;gap:6px;margin-top:8px;}
.s2-weeks-n{font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:36px;line-height:1;color:#e8eaf0;}
.s2-weeks-u{font-size:12px;line-height:16px;color:#7e8a9e;}
.s2-dots{display:flex;gap:6px;margin-top:12px;}
.s2-dot{width:15px;height:15px;border-radius:50%;background:rgba(45,212,191,0.2);border:1px solid rgba(45,212,191,0.2);}
.s2-dot-on{background:rgba(45,212,191,0.9);border:1px solid #2dd4bf;}
.s2-ci-week{font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:22px;color:#e8eaf0;margin-top:8px;}
.s2-ci-p{font-size:11.5px;color:#7e8a9e;margin-top:4px;}
.s2-bar{height:5px;border-radius:9999px;margin-top:12px;overflow:hidden;background:rgba(255,255,255,0.06);}
.s2-bar-fill{width:62%;height:100%;border-radius:999px;background:linear-gradient(90deg,#2dd4bf,#34d399);}

.s2-qa-label{font-size:10.5px;text-transform:uppercase;font-weight:600;color:#7e8a9e;letter-spacing:0.16em;margin:24px 0 10px 2px;}
.s2-qa{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;}
.s2-qa-item{display:flex;flex-direction:column;align-items:center;gap:6px;border-radius:16px;padding:14px 0;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);}
.s2-qa-text{font-size:10.5px;font-weight:500;color:#a9b2c1;}

.s2-learnwrap{padding:16px 24px 0;}
.s2-learn{display:flex;align-items:flex-start;gap:12px;padding:20px;border-radius:24px;background:rgba(167,139,250,0.07);border:1px solid rgba(167,139,250,0.2);}
.s2-learn-ic{width:40px;height:40px;border-radius:12px;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:rgba(167,139,250,0.15);}
.s2-learn-body{flex:1;min-width:0;}
.s2-learn-label{font-size:10.5px;text-transform:uppercase;font-weight:600;color:#a78bfa;letter-spacing:0.16em;}
.s2-learn-title{font-weight:600;font-size:14px;line-height:20px;color:#e8eaf0;margin-top:4px;}
.s2-learn-sum{font-size:11.5px;color:#7e8a9e;line-height:1.5;margin-top:4px;}
.s2-learn-chev{flex-shrink:0;margin-top:4px;}

.s2-nav{position:absolute;bottom:24px;left:50%;transform:translateX(-50%);z-index:50;background:rgba(9,12,20,0.75);border:1px solid rgba(255,255,255,0.10);border-radius:9999px;padding:10px 32px;box-shadow:0 8px 32px rgba(0,0,0,0.45),inset 0 1px 0 rgba(255,255,255,0.12);-webkit-backdrop-filter:blur(28px) saturate(180%);backdrop-filter:blur(28px) saturate(180%);}
.s2-nav-row{display:flex;align-items:center;gap:8px;position:relative;}
.s2-nav-pip{position:absolute;border-radius:9999px;background:rgba(45,212,191,0.15);width:40px;height:40px;top:50%;margin-top:-20px;left:0;}
.s2-nav-item{position:relative;z-index:10;display:flex;align-items:center;justify-content:center;border-radius:9999px;width:40px;height:40px;}
.s2-ico{fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;}

.s3-screen{position:relative;width:390px;height:844px;overflow:hidden;background:#090c14;color:#e8eaf0;font-family:'Satoshi','Inter',system-ui,-apple-system,'Segoe UI',sans-serif;-webkit-font-smoothing:antialiased;}
.s3-glow{position:absolute;top:-140px;left:30px;width:340px;height:300px;border-radius:50%;filter:blur(26px);pointer-events:none;background:radial-gradient(closest-side,rgba(45,212,191,0.13),transparent 70%);z-index:0;}
.s3-status{position:relative;z-index:5;height:32px;padding:0 26px;display:flex;align-items:center;justify-content:space-between;}
.s3-time{font-size:11.5px;font-weight:600;letter-spacing:0.01em;color:#e8eaf0;}
.s3-statusIcons{display:flex;align-items:center;gap:6px;color:rgba(232,234,240,0.85);}
.s3-header{position:relative;z-index:4;padding:12px 24px;display:flex;align-items:center;gap:12px;background:rgba(9,12,20,0.8);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid rgba(255,255,255,0.06);}
.s3-back{flex:0 0 auto;width:22px;height:29px;display:flex;align-items:center;color:#7e8a9e;}
.s3-title{flex:1 1 auto;margin:0;font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:22px;line-height:29px;color:#e8eaf0;}
.s3-badge{flex:0 0 auto;display:inline-flex;align-items:center;gap:6px;padding:5px 10px;border-radius:999px;background:rgba(255,255,255,0.16);border:1px solid rgba(255,255,255,0.24);color:#e8eaf0;font-size:10px;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;line-height:1;}
.s3-dot{width:5px;height:5px;border-radius:50%;background:#e8eaf0;box-shadow:0 0 8px rgba(255,255,255,0.24);}
.s3-main{position:relative;z-index:2;padding:14px 24px 0;}
.s3-hero{text-align:center;}
.s3-eyebrow{margin:0;font-size:10.5px;font-weight:700;letter-spacing:0.16em;text-transform:uppercase;color:#e8eaf0;line-height:13px;}
.s3-heroNum{margin:6px 0 0;font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:40px;line-height:42px;color:#e8eaf0;text-shadow:0 0 44px rgba(45,212,191,0.35);}
.s3-arrow{font-family:'Satoshi','Inter',system-ui,sans-serif;font-style:normal;font-size:26px;color:#2dd4bf;padding:0 5px;vertical-align:3px;}
.s3-heroSub{margin:6px auto 0;max-width:316px;font-size:12.5px;line-height:1.5;color:#a9b2c1;}
.s3-card{margin-top:14px;padding:18px;border-radius:20px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);}
.s3-tabs{display:flex;gap:6px;margin-bottom:14px;}
.s3-tab{flex:1 1 0;height:32px;display:flex;align-items:center;justify-content:center;border-radius:12px;font-size:12.5px;font-weight:500;background:rgba(255,255,255,0.05);color:#c9cdd5;white-space:nowrap;}
.s3-tabOn{background:#2dd4bf;color:#04121a;font-weight:600;}
.s3-chart{display:block;}
.s3-axis{display:flex;align-items:center;justify-content:space-between;margin-top:6px;padding:0 1px;height:16px;}
.s3-axisEnd{font-size:11px;color:#5a6578;font-variant-numeric:tabular-nums;}
.s3-delta{font-size:11px;font-weight:700;color:#e8eaf0;font-variant-numeric:tabular-nums;}
.s3-cardHead{display:flex;align-items:baseline;justify-content:space-between;height:19px;margin-bottom:12px;}
.s3-cardTitle{margin:0;font-size:15px;font-weight:600;color:#e8eaf0;}
.s3-cardTag{font-size:10px;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;color:#e8eaf0;}
.s3-rows{display:flex;flex-direction:column;gap:8px;}
.s3-row{display:flex;align-items:center;gap:10px;}
.s3-rowLabel{flex:0 0 76px;font-size:11.5px;color:#c9cdd5;}
.s3-bar{flex:1 1 auto;height:26px;border-radius:8px;background:rgba(255,255,255,0.035);overflow:hidden;}
.s3-fill{display:block;height:100%;border-radius:8px;background:linear-gradient(90deg,rgba(45,212,191,0.13) 0%,#2dd4bf 100%);box-shadow:0 0 18px rgba(45,212,191,0.20);}
.s3-rowVals{flex:0 0 72px;display:flex;align-items:center;justify-content:flex-end;gap:8px;}
.s3-val{font-size:12.5px;color:#e8eaf0;font-variant-numeric:tabular-nums;}
.s3-dlt{font-size:11.5px;font-weight:700;color:#2dd4bf;font-variant-numeric:tabular-nums;}
.s3-foot{margin:14px 2px 0;font-size:11px;line-height:1.5;color:#5a6578;}
.s3-nav{position:absolute;left:50%;bottom:24px;transform:translateX(-50%);z-index:20;padding:10px 32px;border-radius:999px;background:rgba(9,12,20,0.75);backdrop-filter:blur(28px) saturate(180%);-webkit-backdrop-filter:blur(28px) saturate(180%);border:1px solid rgba(255,255,255,0.10);box-shadow:0 8px 32px rgba(0,0,0,0.45),inset 0 1px 0 rgba(255,255,255,0.12);}
.s3-navRow{position:relative;display:flex;align-items:center;gap:8px;}
.s3-navPip{position:absolute;top:0;left:48px;width:40px;height:40px;border-radius:50%;background:rgba(45,212,191,0.15);}
.s3-navItem{position:relative;z-index:1;width:40px;height:40px;display:flex;align-items:center;justify-content:center;color:rgba(255,255,255,0.40);}
.s3-navOn{color:#2dd4bf;}
.s3-rowNote{font-size:11px;line-height:15px;color:#5a6578;margin-left:auto}

:where(.s4-screen,.s4-screen *,.s4-screen *::before,.s4-screen *::after){box-sizing:border-box;margin:0;padding:0;border:0}
.s4-screen{position:relative;width:390px;height:844px;overflow:hidden;background:#090c14;font-family:'Satoshi',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;-webkit-font-smoothing:antialiased;color:#e8eaf0}
.s4-header{position:relative;z-index:40;display:flex;align-items:center;gap:16px;padding:16px 24px;background:rgba(9,12,20,0.8);border-bottom:1px solid rgba(255,255,255,0.06)}
.s4-back{flex:0 0 auto;width:36px;height:36px;margin-left:-8px;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#7e8a9e}
.s4-h1{font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:24px;line-height:32px;color:#e8eaf0}
.s4-main{padding:32px 24px 0}
.s4-card{border-radius:16px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);overflow:hidden}
.s4-cardpad{padding:24px}
.s4-card2{margin-top:20px}
.s4-cardhead{display:flex;align-items:center;gap:12px;margin-bottom:20px}
.s4-tile{flex:0 0 auto;width:44px;height:44px;border-radius:12px;display:flex;align-items:center;justify-content:center;background:rgba(45,212,191,0.12)}
.s4-titlewrap{display:flex;flex-direction:column}
.s4-title{font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:20px;line-height:28px;color:#e8eaf0}
.s4-sub{font-size:12px;line-height:16px;color:#7e8a9e}
.s4-rows{display:flex;flex-direction:column;gap:8px}
.s4-row{display:flex;align-items:center;gap:12px;width:100%;padding:12px;border-radius:12px;background:rgba(255,255,255,0.03);text-align:left}
.s4-chip{flex:0 0 auto;padding:2px 8px;border-radius:4px;font-size:10px;line-height:14px;text-transform:uppercase;background:rgba(45,212,191,0.12);color:#2dd4bf}
.s4-name{flex:1 1 0%;min-width:0;font-size:14px;line-height:20px;color:#e8eaf0}
.s4-portion{font-size:12px;line-height:16px;margin-left:6px;color:#7e8a9e}
.s4-kcal{flex:0 0 auto;font-size:12px;line-height:16px;color:#7e8a9e;font-variant-numeric:tabular-nums}
.s4-chev{flex:0 0 auto;color:#4b5563}
.s4-total{margin-top:8px;padding-right:4px;text-align:right;font-size:12px;line-height:16px;color:#2dd4bf;font-variant-numeric:tabular-nums}
.s4-logger{margin-top:16px;padding-top:16px;border-top:1px solid rgba(255,255,255,0.06)}
.s4-logtop{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}
.s4-logtitle{font-size:10.5px;line-height:14px;text-transform:uppercase;font-weight:600;letter-spacing:0.16em;color:#7e8a9e}
.s4-logcount{font-size:11px;line-height:14px;color:#5a6578;font-variant-numeric:tabular-nums}
.s4-pills{display:flex;flex-wrap:wrap;gap:8px}
.s4-pill{display:inline-flex;align-items:center;gap:6px;padding:8px 12px;border-radius:9999px;font-size:12px;line-height:16px;font-weight:600}
.s4-pill-done{background:rgba(52,211,153,0.14);color:#34d399;border:1px solid rgba(52,211,153,0.3)}
.s4-pill-todo{background:rgba(255,255,255,0.04);color:#a9b2c1;border:1px solid rgba(255,255,255,0.08)}
.s4-dot{flex:0 0 auto;width:12px;height:12px;border-radius:9999px;border:1.5px solid #5a6578}
.s4-nav{position:absolute;z-index:50;bottom:24px;left:50%;transform:translateX(-50%);padding:10px 32px;border-radius:9999px;background:rgba(9,12,20,0.75);border:1px solid rgba(255,255,255,0.10);box-shadow:0 8px 32px rgba(0,0,0,0.45),inset 0 1px 0 rgba(255,255,255,0.12)}
.s4-navrow{position:relative;display:flex;align-items:center;gap:8px}
.s4-navdot{position:absolute;left:96px;top:50%;margin-top:-20px;width:40px;height:40px;border-radius:9999px;background:rgba(45,212,191,0.15)}
.s4-tab{position:relative;z-index:10;display:flex;align-items:center;justify-content:center;width:40px;height:40px;border-radius:9999px}

.s5-screen{position:relative;width:390px;height:844px;overflow:hidden;background:#090c14;font-family:'Satoshi','Inter',system-ui,-apple-system,'Helvetica Neue',Arial,sans-serif;color:#e8eaf0;-webkit-font-smoothing:antialiased}
.s5-screen *{box-sizing:border-box;margin:0;padding:0}

.s5-header{padding:16px 24px;background:rgba(9,12,20,0.8);border-bottom:1px solid rgba(255,255,255,0.06)}
.s5-hrow{display:flex;align-items:center;gap:16px}
.s5-back{width:36px;height:36px;margin-left:-8px;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#7e8a9e;flex-shrink:0}
.s5-title{font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:24px;line-height:32px;color:#e8eaf0}

.s5-main{padding:32px 24px}
.s5-card{border-radius:16px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);overflow:hidden}
.s5-cardpad{padding:24px}

.s5-cardhead{display:flex;align-items:center;gap:12px;margin-bottom:20px}
.s5-icontile{width:44px;height:44px;border-radius:12px;background:rgba(45,212,191,0.12);display:flex;align-items:center;justify-content:center;flex-shrink:0}
.s5-plantitle{font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:20px;line-height:28px;color:#e8eaf0}
.s5-planmeta{font-size:12px;line-height:16px;color:#7e8a9e}

.s5-week{display:flex;gap:6px;margin-bottom:12px}
.s5-day{flex:1 1 0;height:54px;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;background:transparent;border:1px solid rgba(255,255,255,0.04)}
.s5-day-has{background:rgba(255,255,255,0.04);border-color:rgba(255,255,255,0.07)}
.s5-day-on{background:rgba(45,212,191,0.16);border-color:rgba(45,212,191,0.45)}
.s5-dl{font-size:12px;line-height:14px;font-weight:600;color:#5a6578}
.s5-day-has .s5-dl{color:#e8eaf0}
.s5-day-on .s5-dl{color:#2dd4bf}
.s5-ds{font-size:10px;line-height:12px;font-weight:600;color:#404858;letter-spacing:0.01em}
.s5-day-has .s5-ds{color:#7e8a9e}
.s5-day-on .s5-ds{color:#2dd4bf}

.s5-session{font-size:12px;line-height:18px;color:#7e8a9e;padding:0 2px;margin-bottom:12px}

.s5-rows{display:flex;flex-direction:column;gap:8px}
.s5-row{display:flex;align-items:center;gap:12px;padding:12px;border-radius:12px;background:rgba(255,255,255,0.03);text-align:left}
.s5-thumb{position:relative;width:48px;height:48px;border-radius:10px;overflow:hidden;background:#fff;flex-shrink:0}
.s5-figsvg{display:block}
.s5-loop{position:absolute;right:3px;top:3px;width:16px;height:16px;border-radius:999px;background:rgba(4,8,14,0.78);display:flex;align-items:center;justify-content:center}
.s5-loopdot{width:6px;height:6px;border-radius:999px;background:#2dd4bf}
.s5-ename{flex:1 1 auto;font-size:14px;line-height:20px;color:#e8eaf0;white-space:nowrap}
.s5-sets{font-size:12px;line-height:16px;color:#7e8a9e;font-variant-numeric:tabular-nums;flex-shrink:0}
.s5-chev{flex-shrink:0;display:flex;color:#4b5563}

.s5-nav{position:absolute;bottom:24px;left:50%;transform:translateX(-50%);background:rgba(9,12,20,0.75);border:1px solid rgba(255,255,255,0.10);border-radius:999px;padding:10px 32px;box-shadow:0 8px 32px rgba(0,0,0,0.45),inset 0 1px 0 rgba(255,255,255,0.12)}
.s5-navrow{position:relative;display:flex;align-items:center;gap:8px}
.s5-navpill{position:absolute;left:96px;top:50%;margin-top:-20px;width:40px;height:40px;border-radius:999px;background:rgba(45,212,191,0.15)}
.s5-tab{position:relative;z-index:1;width:40px;height:40px;border-radius:999px;display:flex;align-items:center;justify-content:center;color:rgba(255,255,255,0.40)}
.s5-tab-on{color:#2dd4bf}

