.s6-header{position:relative;z-index:40;display:flex;align-items:center;gap:16px;padding:16px 24px;background:rgba(9,12,20,0.8);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid rgba(255,255,255,0.06);}
.s6-back{display:flex;align-items:center;justify-content:center;padding:8px;margin-left:-8px;border-radius:20px;color:#7e8a9e;}
.s6-h1{margin:0;font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:24px;line-height:1.15;color:#e8eaf0;}

.s6-main{position:relative;z-index:1;display:flex;flex-direction:column;gap:20px;padding:32px 24px;}

.s6-upload{display:flex;align-items:center;gap:12px;width:100%;padding:16px;border-radius:32px;text-align:left;background:rgba(45,212,191,0.08);border:1px solid rgba(45,212,191,0.2);}
.s6-uploadicon{flex:0 0 auto;width:40px;height:40px;border-radius:26px;display:flex;align-items:center;justify-content:center;background:rgba(45,212,191,0.14);}
.s6-uploadtext{flex:1;min-width:0;}
.s6-uploadtitle{margin:0;font-size:14px;font-weight:600;color:#e8eaf0;letter-spacing:-0.005em;line-height:1.3;}
.s6-uploadsub{margin:2px 0 0;font-size:11.5px;line-height:1.45;color:#7e8a9e;}

.s6-card{padding:24px;border-radius:32px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);}
.s6-cardhead{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:4px;}
.s6-cardtitle{margin:0;font-size:16px;font-weight:600;color:#e8eaf0;letter-spacing:-0.01em;line-height:1.3;}
.s6-carddate{font-size:11px;color:#7e8a9e;font-variant-numeric:tabular-nums;white-space:nowrap;}
.s6-cardsub{margin:0 0 16px;font-size:11.5px;line-height:1.45;color:#7e8a9e;}

.s6-panel{margin:0 0 8px 2px;font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:0.14em;color:#7e8a9e;line-height:1.3;}
.s6-rows{display:flex;flex-direction:column;gap:10px;}

.s6-row{padding:14px;border-radius:26px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.05);}
.s6-rowtop{display:flex;align-items:center;gap:8px;}
.s6-name{flex:1;min-width:0;font-size:14px;font-weight:500;color:#e8eaf0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.s6-val{font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-size:20px;line-height:1;color:#e8eaf0;font-variant-numeric:tabular-nums;}
.s6-unit{font-size:10.5px;color:#7e8a9e;}

.s6-gauge{margin-top:12px;}
.s6-track{position:relative;height:10px;border-radius:9999px;background:rgba(255,255,255,0.06);}
.s6-band{position:absolute;top:0;bottom:0;border-radius:9999px;background:rgba(52,211,153,0.22);border:1px solid rgba(52,211,153,0.25);}
.s6-dot{position:absolute;top:50%;width:14px;height:14px;border-radius:9999px;background:#0d111b;border:2.5px solid #2dd4bf;transform:translate(-50%,-50%);}
.s6-scale{display:flex;justify-content:space-between;align-items:baseline;margin-top:6px;}
.s6-tick{font-size:10px;line-height:1.3;color:#5a6578;font-variant-numeric:tabular-nums;}
.s6-ticklabel{font-size:10px;line-height:1.3;color:#5a6578;}

.s6-rowmuted{display:flex;align-items:center;gap:8px;padding:14px;border-radius:26px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.05);}
.s6-namemuted{flex:1;min-width:0;font-size:14px;font-weight:500;color:#a9b2c1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.s6-nottested{font-size:11px;line-height:1.3;color:#7e8a9e;white-space:nowrap;}

.s6-foot{margin:16px 0 0;font-size:10.5px;line-height:1.5;color:#5a6578;}

.s6-nav{position:absolute;left:50%;bottom:24px;transform:translateX(-50%);z-index:50;padding:10px 32px;border-radius:9999px;background:rgba(9,12,20,0.75);border:1px solid rgba(255,255,255,0.10);backdrop-filter:blur(28px) saturate(180%);-webkit-backdrop-filter:blur(28px) saturate(180%);box-shadow:0 8px 32px rgba(0,0,0,0.45), inset 0 1px 0 rgba(255,255,255,0.12);}
.s6-navrow{position:relative;display:flex;align-items:center;gap:8px;}
.s6-navpill{position:absolute;left:0;top:50%;margin-top:-20px;width:40px;height:40px;border-radius:9999px;background:rgba(45,212,191,0.15);}
.s6-navitem{position:relative;z-index:10;width:40px;height:40px;border-radius:9999px;display:flex;align-items:center;justify-content:center;}
